import {CINEMATIC_DURATION,cinematicState,drawCinematic} from './cinematic.js';
export function mountMontage({root,button,replay,reduced=false,onClose=()=>{}}){let started=0,frame=0,active=false,lastScene=-1;const canvas=root.querySelector('[data-cinematic-canvas]'),ctx=canvas?.getContext?.('2d');let width=0,height=0;
 const close=()=>{if(!active)return;active=false;root.hidden=true;cancelAnimationFrame(frame);onClose();};
 const paint=now=>{if(!active)return;const elapsed=now-started;if(elapsed>=CINEMATIC_DURATION){close();return;}const state=cinematicState(elapsed);if(state.index!==lastScene){lastScene=state.index;root.dataset.scene=String(state.index);root.querySelector('[data-montage-kicker]').textContent=state.scene.kicker;root.querySelector('[data-montage-title]').textContent=state.scene.title;root.querySelector('[data-montage-detail]').textContent=state.scene.detail;}
 if(ctx){const w=root.clientWidth||innerWidth,h=root.clientHeight||innerHeight;if(w!==width||h!==height){width=w;height=h;const d=Math.min(typeof devicePixelRatio==='number'?devicePixelRatio:1,1.5);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);}drawCinematic(ctx,width,height,elapsed);}root.style.setProperty('--progress',`${elapsed/CINEMATIC_DURATION*100}%`);frame=requestAnimationFrame(paint);};
 const open=()=>{if(active)cancelAnimationFrame(frame);active=true;root.hidden=false;lastScene=-1;started=performance.now();frame=requestAnimationFrame(paint);};
 button.onclick=close;replay.onclick=open;window.addEventListener('keydown',e=>{if(active&&e.code==='Space'){e.preventDefault();e.stopImmediatePropagation();close();}},true);if(!reduced)open();return {open,close,get active(){return active}};}
